-- Run against a disposable Supabase database after all migrations; all changes roll back.
begin;
create schema phase_two_test;
grant usage on schema phase_two_test to anon,authenticated;
create function phase_two_test.check(ok boolean) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'Phase two assertion failed'; end if; end $$;
create function phase_two_test.denied(statement text,code text default 'PT404') returns void language plpgsql as $$
begin
 begin execute statement;
 exception when others then if sqlstate=code then return; end if; raise; end;
 raise exception 'Unexpectedly allowed: %',statement;
end $$;
